WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (42::BIGINT, 'El curso es muy pesado pero la profe explica muy bien, las clases asincrónicas a veces confunden un poco pero si uno le pregunta explica sin enojarse. Incluso me llegó a ayudar con materia de otro curso (mate financiera). Tareas eran entrega completa pero creo que lo va a cambiar'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'b4669a1918d9af8e0fc322b7f76be753bad38b47941809beae1c917f396d7671'::TEXT, ARRAY[2361]::BIGINT[]),
    (42::BIGINT, 'Es una excelente profesora, en estos años de universidad puedo decir que es de las mejores. Explica todas las veces que quieras y no se enoja, distribuye equilibradamente las evaluaciones, deja un espacio al final para los que tienen dudas y funciona demasiado bien. En general es magnifica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-02-07T00:00:00+00:00'::TIMESTAMPTZ, '0774d5b68e2a870615cfbe537a6b099964c63cf42b886eae8c807684d56b671e'::TEXT, ARRAY[2366]::BIGINT[]),
    (42::BIGINT, 'Es muy buena profe, trata de que todos vayamos a un mismo ritmo, si usa aula invertida y eso te hace ser mas consiente de cada tema, si tiene dudas ella te va a explicar y no se molesta para nada, hace muchos trabajos en grupo por lo que seria ideal tener un buen grupo para facilitar el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2025-08-09T00:00:00+00:00'::TIMESTAMPTZ, '77ff9baad80f93a457dc078d9779fa7350086f61a78746656f1fe461d85c511b'::TEXT, ARRAY[1707]::BIGINT[]),
    (42::BIGINT, 'El curso se pasa fácil, hay tareas todas las semanas, son fáciles pero hay que sacar el tiempo, busque buen equipo de trabajo, créditos fáciles. Si tiene un semestre pesado son créditos seguros'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2025-07-17T00:00:00+00:00'::TIMESTAMPTZ, '2d0a86c5b7c53c49ab0cd8067fbd6c8a8a0cc864e956a884ac8c7934eaa3b42d'::TEXT, ARRAY[92]::BIGINT[]),
    (42::BIGINT, 'Es cierto que hay que ser autodidacta por que aplica muy fuertemente el aula invertida, lo cual en muchas ocasiones puede ser frustrante, pero lo enseña a uno a resolver los ejercios más allá que memorizar como se hacen las cosas, lo enseña a entender la lógica de las cosas. Es dura, pero sí aprende'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Da crédito extra']::TEXT[], '2025-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'f613cbade292940988a05f97d5e552c033414a2f2224eae1033fee0fe49290c2'::TEXT, ARRAY[1707]::BIGINT[]),
    (42::BIGINT, 'Básicamente hay que ser autodidacta. A la profesora no le gusta explicar en clase, la materia que da por aula invertida es confusa, las soluciones de prácticas vienen incompletas y tiende a enojarse cuando uno le pregunta, al punto de victimizarse. Los examenes tienen instrucciones confusas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'ab57dc12bff9c859e5c946281dd4d398ca40ebd1f258f6d60264dea88f6d6b81'::TEXT, ARRAY[2361]::BIGINT[]),
    (42::BIGINT, 'Es llevar el curso solo, no se realizan explicaciones en clase, a la profesora le molesta aclarar duda y que uno pregunte. Nada de las prácticas y/o trabajos en clase se revisan, simplemente califica por entrega, es bueno para la nota, pero en el examen castiga por cosas no explicadas. No recomiendo'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'ba75b5a6997909c23e7529ee255ff88d0f8e8e6fe2de569eea77ca2906a9acd1'::TEXT, ARRAY[2361]::BIGINT[]),
    (42::BIGINT, 'No explica, asume que usted ya sabe las cosas y cuando le pregunta no le responde lo que se le preguntó. Deja trabajos todas las semanas muy largos y confusos. Usted tiene que ser autodidacta y da presentaciones muy incompletas y cortas. Si se le menciona un error se victimiza'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-01-10T00:00:00+00:00'::TIMESTAMPTZ, 'e5b28ed1951a96a8496ec1412987c5f43ae68bcdb288abad35edd755f320ee85'::TEXT, ARRAY[2366, 2361, 1707]::BIGINT[]),
    (42::BIGINT, 'A veces es un poco enredado entender las instrucciones de los trabajos pero una ventaja es que deja usar plantillas y ver sus apuntes en los examenes.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-12-15T00:00:00+00:00'::TIMESTAMPTZ, '1f854bf7145564bf7f0c08af7e18673a930e32fbff18ac6040c2d04dface8967'::TEXT, ARRAY[1707]::BIGINT[]),
    (42::BIGINT, 'Las clases son aburridas, deja trabajos todas las semanas, le gusta hacer aula invertida y las instrucciones de todos los trabajos son mayormente confusas. Para el proyecto final hay que tener buen grupo de trabajo para sobrevivir'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'ec324987220b6e6992310b77ea4c71e93545ae2dcdff626c2aa5420dd91faf0e'::TEXT, ARRAY[2442]::BIGINT[]),
    (42::BIGINT, 'Los trabajos semanales que deja son muy largos, si matricula con ella busque a alguien que conozca de contabilidad porque piensa que usted ya sabe, las presentaciones que deja como retroalimentación no muy malas, eso si le recomiendo que participe en clases.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Muchos exámenes']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, '98c15a2a51809c2701a1e21727e2197647befd521556097d464e0b65d881b3ce'::TEXT, ARRAY[1206]::BIGINT[]),
    (42::BIGINT, 'Pidale los trabajos a estudiantes viejos, repite los trabajos, porq por cuenta propia son largos y no hay material en clase para guiarse como tal. la clase es re corta para que lo tengan en cuenta.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2023-11-17T00:00:00+00:00'::TIMESTAMPTZ, '5ff1548a4cd3f4a85c7ce82cde1dd6d0e331fdafd42ff68fb4fb530092987193'::TEXT, ARRAY[1206]::BIGINT[]),
    (42::BIGINT, 'No explica,le gusta trabajar en aula invertida , uno le pregunta algo y mas bien lo enreda. Se la pasa comparando admi con las ingenierias, lo cual no virene al caso, deja tareas todas las semanas lo cual es tedioso, tareas valen muy poquito para todo lo que hay que hacer, pesima la verdad.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c08576d952884629744e9d2f5efb090ba3b3b95b2199739548bafb0a4229068c'::TEXT, ARRAY[92]::BIGINT[]),
    (42::BIGINT, 'Es buena gente, pero pésima retroalimentando y se explica muy confusa. Siempre le va a responder sus correos, pero no con lo que usted le está consultando (o puede ser que si le responda lo que usted necesita después del noveno correo). Prepárese para las desveladas por trabajos que valen poco.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-09-08T00:00:00+00:00'::TIMESTAMPTZ, '1dc92fcfc2a6b59aa716f6497f46a284a296a0141f0e06a799a4f21fb9a7f0c4'::TEXT, ARRAY[1206]::BIGINT[]),
    (42::BIGINT, 'La explicación de ella es excelente, pero sus metodologías de evaluación son muy malas, así cuesta mucho aprender. Es demasiado repugnante dando retroalimentaciones, que son pocas claras y respondiendo mensajes.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, '49090a5e83d71fb11f8f4faa61462b63b8bbdf0bfa0b8b7a031b2eccdb4489dc'::TEXT, ARRAY[1708]::BIGINT[]),
    (42::BIGINT, 'Las clases las hace asincrónicas mayoritariamente, hace mucho trabajo en grupo pero la profe es super accesible y buena gente, si lo matricula y hace los trabajos, pasa.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2022-01-29T00:00:00+00:00'::TIMESTAMPTZ, '52ebe5f6bc41f3b87b77a64b1581baa45bf1155fd3e3f3019bf619650a90bb65'::TEXT, ARRAY[2366, 2361, 1707]::BIGINT[]),
    (42::BIGINT, 'Buena profesora, deja trabajos pero son bastante sencillas además de que se aprende. Las clases casi que todas son asincrónicas pero sube los videos con la explicación. Además de que su forma de evaluar no son solo exámenes de porcentajes altos por lo que se hace más sencillo pasar el curso.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '3cb443d25bce75f99ee64914eaa74f2664d1cd2abada772008aecc8c59363fcb'::TEXT, ARRAY[1206]::BIGINT[]),
    (42::BIGINT, 'En virtual, muy buena. Tiene ciertas cosillas que no me gustaron, pero todo bien.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-28T00:00:00+00:00'::TIMESTAMPTZ, '4f504074888bb97207a837dd9f1e1303b5b07b991f87173dd8d7ea6aa21c5a6d'::TEXT, ARRAY[1206]::BIGINT[]),
    (42::BIGINT, 'Da clases virtuales sincrónicas y asincrónicas. Los exámenes los realiza en dos partes, uno individual y el otro grupal. Las clases son cortas, hay que practicar y la profesora es muy accesible para ayudar. Si lo matricula, lo pasa.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2020-12-26T00:00:00+00:00'::TIMESTAMPTZ, '77be48fcbaa1a4ef248715e92d9c8a0a5dc216c04ea03509f9188a9fc75a2958'::TEXT, ARRAY[1707]::BIGINT[]),
    (42::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '246b2616dd3b6b58bd45183ea8a7b5e6fc24c9fae6bb539b2ce74f53f2ee1ab1'::TEXT, ARRAY[1206]::BIGINT[]),
    (42::BIGINT, 'Un amor de persona, super amable y compresible. Y como profe muy buena, explica bastante claro, examenes faciles, califica suave'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-02T00:00:00+00:00'::TIMESTAMPTZ, '2d159ffa26732f36b2e0bed7dd14f19a3edee66e58c1e4085fc49bff5e784e79'::TEXT, ARRAY[1206]::BIGINT[]),
    (42::BIGINT, 'Muy mala profesora. No la recomiendo'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '9751c0f2354054df09a5b203ef215a6e8cd82d53f9f53fb12588f8c7cc28b28e'::TEXT, ARRAY[2361]::BIGINT[]),
    (42::BIGINT, 'Muy buena profe, explica bien, es muy amable y ayuda a los estudiantes. Los examenes son sencillos si hace bien las prácticas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'ae4d571a0c90c08f8a052f431e17949fe2f93882eedf3d0bb12635c31d805500'::TEXT, ARRAY[1206]::BIGINT[]),
    (42::BIGINT, 'Buena profe, trata de que el estudiante aprenda. Los examenes los hace en 2 partes para ayudar al estudiante. Las clases son un poco aburridas. Es exigente en las exposiciones.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-26T00:00:00+00:00'::TIMESTAMPTZ, '2cfd12ae1fc3e40b7dc678902841e7147c44ae2d3337bdad9aafb503e9f286b7'::TEXT, ARRAY[1707]::BIGINT[]),
    (42::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '68aea304460bab4c75ec9c66988e43c5be4fe86a52f4dc4266f20182f518e5cf'::TEXT, ARRAY[1206]::BIGINT[]),
    (42::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2017-10-13T00:00:00+00:00'::TIMESTAMPTZ, 'd5fa0a1e5416f2cf96f77db7e9cabe579ab70f8bbc71b30f7b172c8e50196d79'::TEXT, ARRAY[1206]::BIGINT[]),
    (42::BIGINT, 'Hace examenes en pareja. No explica bien. Le falta mucha experiencia.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '99508387679bd26f0af62956b6734645c5bb1fc9622305d00867cbeebf192eba'::TEXT, ARRAY[2394]::BIGINT[]),
    (42::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a7c7636ed87a4e7d06c6609f8c0bce9a3e5121283aa86c9bc48b2dffed7c9ef6'::TEXT, ARRAY[1707, 2361]::BIGINT[]),
    (42::BIGINT, 'Buena profe, a veces su explicaciones no son muy claras'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '1da91ce0680ad396bbbd665d454cb096a86bc2f8ee11fcb0c46cb71a4b6b58ea'::TEXT, ARRAY[1707]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
